from analyze import load,p
def metrics(r): return f"{r.get('clicks',0)} / {r.get('impressions',0)} / {r.get('ctr',0)*100:.2f}% / {r.get('position',0):.2f}"
lines=['# SquarePic GSC traffic decline investigation','', 'Collected October 18, 2026, Asia/Calcutta. Property sc-domain:squarepic.io. Web search only. Latest returned daily row is October 14; October 15 onward is excluded. GSC dates use Pacific Time. All comparisons below contain equal numbers of complete days.','', '## Complete-period comparisons','', '| Period | Clicks | Impressions | CTR | Average position |','|---|---:|---:|---:|---:|']
for n,label in [('previous','Aug 20 to Sep 16, 28 days'),('current','Sep 17 to Oct 14, 28 days'),('priorweek','Oct 1 to Oct 7, 7 days'),('recent','Oct 8 to Oct 14, 7 days')]:
 r=load(n+'-totals')[0]; lines.append(f"| {label} | {r['clicks']} | {r['impressions']} | {r['ctr']*100:.2f}% | {r['position']:.2f} |")
for dim in ['page','query','device','country']:
 for before,after in [('previous','current'),('priorweek','recent')]:
  a={r['keys'][0]:r for r in load(after+'-'+dim)}; b={r['keys'][0]:r for r in load(before+'-'+dim)}
  lines+=['',f'## {dim}: {before} versus {after}','','Metrics are clicks / impressions / CTR / average position. Missing query rows mean unreported, not necessarily zero. Query rows omit anonymized searches; do not reconcile them to property totals. Page and property aggregation can differ.','','| Dimension | Before | After | Click difference | Impression difference |','|---|---:|---:|---:|---:|']
  for k in sorted(a.keys()|b.keys(),key=lambda k:a.get(k,{}).get('clicks',0)-b.get(k,{}).get('clicks',0))[:15]:
   x=b.get(k,{}); y=a.get(k,{})
   lines.append(f"| {k} | {metrics(x)} | {metrics(y)} | {y.get('clicks',0)-x.get('clicks',0):+} | {y.get('impressions',0)-x.get('impressions',0):+} |")
lines+=['','## Diagnosis and limits','','The daily trend peaks in early/mid September and declines before the October 7 to 9 repository changes. Git commit dates are not deployment evidence. The September 2026 spam update ran September 24 to October 8; timing overlaps part of the decline but cannot establish causation. Source: https://status.search.google.com/summary','','Aggregate position improves as impressions fall. This can reflect a changing mix of queries and fewer low-ranking impressions; it does not prove that every query improved. Mobile and individual square-image queries need separate treatment. Lower demand is plausible but not established without independent trend data. Competitor displacement, SERP changes, and AI-result effects are not proven by this export.','','Homepage URL Inspection passes: indexed, crawl allowed, successful fetch, matching Google/user canonical, last crawl October 17. Calculator also passes, but its stored last crawl is September 21, before October edits. Thus those calculator changes cannot yet be credited with recovery or blamed for this decline based on this stored inspection. Live homepage, upscaler and Reels URLs return 200, permit indexing, and self-canonicalize. Root host redirects to www. These samples do not rule out all historical or sitewide crawl issues.','','Submitted sitemap has zero errors and zero warnings and was downloaded October 15. Its indexed=0 field is not an indexed-URL count to interpret as deindexation; use URL Inspection. Manual Actions and Security Issues UI reports were not checked; the API evidence does not establish absence of a penalty.','','## Recommended next steps','','1. Prioritize the homepage queries square pic, squarepic and square image. Compare their device/country-specific rankings and live search snippets before changing titles or copy. Separate brand demand from generic square-photo intent.','2. Inspect calculator and Reels query losses individually. The calculator has stale stored crawl evidence; verify the latest deployed content and request indexing through GSC after confirming it is ready. No indexing request was made in this investigation.','3. Verify mobile loading and editor usability on the deployed site, especially for India. GSC measures clicks before users use the tool, so editor friction alone does not explain lower clicks.','4. Recheck complete seven-day windows when new data arrives. Avoid broad rollbacks based on the aggregate position or the partial final days.','5. Check Manual Actions, Security Issues and Page Indexing in the GSC UI before ruling out those causes.','','Raw JSON responses, collection script, live fetch evidence and inspection responses are saved beside this report. No website settings or code were changed.']
(p/'GOOGLE-API-REPORT-squarepic.io.md').write_text('\n'.join(lines),encoding='utf-8')
